import fs from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const sha=b=>createHash('sha256').update(b).digest('hex');
const candidate=JSON.parse(fs.readFileSync('.runtime/board-card-icon-20261126/candidate.json'));
for(const f of [...candidate.files,...candidate.artifacts])assert.equal(sha(fs.readFileSync(f.path)),f.sha256,f.path);
assert.equal(sha(fs.readFileSync('apps/web/dist/openblock-vendor/openblock-gui.js')),candidate.checks.guiWholeBytes.split(';')[0]);
const html=fs.readFileSync('.runtime/board-icon-independent-20261126/layout.html','utf8');
for(const state of ['baseline','missing','busy','failed','ready','unsupported','offline'])assert.ok(html.includes(`data-case="${state}"`));
assert.equal((html.match(/data-cfzn-library-card=/g)||[]).length,21);
assert.ok(!html.includes('class="cfzn-card-footer"'));
assert.ok(html.includes('跨行长名称与完整说明示例'));
assert.ok(html.includes('说明保持完整显示，不裁切或省略。'));
assert.ok(html.includes('grid-auto-rows: 1fr'));
const generator=fs.readFileSync('.runtime/board-card-icon-20261126/make-layout.mjs','utf8');
assert.ok(generator.includes('new Set(row.cards.map(c=>JSON.stringify(c.size))).size===1'));
const result={result:'PASS source/artifact/real React fixture structure',sourceHashes:candidate.files,artifacts:candidate.artifacts,renderedCases:7,cardsPerCase:3,uniformMeasurementAssertionPresent:true,geometryExecuted:false,realDownloadVerified:false};
fs.mkdirSync('tests/evidence/board-icon-20261126',{recursive:true});
fs.writeFileSync('tests/evidence/board-icon-20261126/final-audit.json',JSON.stringify(result,null,2));
console.log('PASS final frozen hashes, unchanged GUI, actual React fixture 7×3 cards, no controller footer; geometry not executed.');
